<script setup>
import {computed,onMounted,ref} from 'vue';import {del,get,post,put} from '../api/client';import DataTable from '../components/DataTable.vue';
const props=defineProps({user:Object}),tab=ref('users'),users=ref([]),roles=ref([]),permissions=ref([]),sessions=ref([]),audits=ref({items:[],page:1,pages:1}),message=ref(''),resetLink=ref('');const userForm=ref({}),roleForm=ref({}),auditAction=ref(''),auditUser=ref(''),auditPage=ref(1);const can=p=>props.user.permissions.includes(p);
async function loadUsers(){if(can('user:view'))users.value=await get('/users')}async function loadRoles(){if(can('role:view')){roles.value=await get('/roles');permissions.value=await get('/permissions')}}async function loadSessions(){if(can('session:manage'))sessions.value=await get('/sessions')}async function loadAudits(page=1){if(can('audit:view')){auditPage.value=page;audits.value=await get(`/audit-logs?action=${encodeURIComponent(auditAction.value)}&username=${encodeURIComponent(auditUser.value)}&page=${page}`)}}
onMounted(()=>Promise.all([loadUsers(),loadRoles()]));async function switchTab(value){tab.value=value;if(value==='devices')await loadSessions();if(value==='audit')await loadAudits()}
function newUser(){userForm.value={username:'',display_name:'',email:'',mobile:'',password:'',role_ids:[]}}function editUser(row){userForm.value={...row,role_ids:row.roles.map(r=>r.id)}}async function saveUser(){try{if(userForm.value.id)await put(`/users/${userForm.value.id}`,userForm.value);else await post('/users',userForm.value);message.value='用户已保存';userForm.value={};await loadUsers()}catch(e){message.value=e.message}}async function setStatus(row){try{await put(`/users/${row.id}/status`,{status:row.status==='active'?'disabled':'active'});await loadUsers()}catch(e){message.value=e.message}}async function createReset(row){try{const value=await post(`/users/${row.id}/reset-token`,{});resetLink.value=`${location.origin}/#reset=${value.token}`;message.value='重置链接一小时内有效，只显示本次结果'}catch(e){message.value=e.message}}
function newRole(){roleForm.value={role_code:'',role_name:'',description:'',permission_ids:[]}}function editRole(row){roleForm.value={...row,permission_ids:[...row.permission_ids]}}async function saveRole(){try{if(roleForm.value.id)await put(`/roles/${roleForm.value.id}`,roleForm.value);else await post('/roles',roleForm.value);message.value='角色已保存';roleForm.value={};await loadRoles()}catch(e){message.value=e.message}}async function removeRole(row){if(!confirm(`确认删除角色 ${row.role_name}？`))return;try{await del(`/roles/${row.id}`);await loadRoles()}catch(e){message.value=e.message}}async function revoke(row){try{await del(`/sessions/${row.id}`);await loadSessions()}catch(e){message.value=e.message}}
function device(value){if(!value)return'未知设备';const browser=/Edg\//.test(value)?'Edge':/Chrome\//.test(value)?'Chrome':/Firefox\//.test(value)?'Firefox':/Safari\//.test(value)?'Safari':'其他浏览器',system=/Windows/.test(value)?'Windows':/Android/.test(value)?'Android':/iPhone|iPad/.test(value)?'iOS':/Mac OS/.test(value)?'macOS':/Linux/.test(value)?'Linux':'未知系统';return`${browser} · ${system}`}
const actionNames={'user.create':'创建用户','user.update':'修改用户','user.status':'变更用户状态','user.reset_token':'生成重置链接','role.create':'创建角色','role.update':'修改角色','role.delete':'删除角色','session.revoke':'撤销会话','schedule.update':'修改定时任务'};
const userCols=[{label:'用户名',key:'username'},{label:'显示名称',key:'display_name'},{label:'角色',key:'roles',format:v=>v.map(r=>r.role_name).join('、')},{label:'状态',key:'status',format:v=>v==='active'?'启用':'禁用'},{label:'上次登录',key:'last_login_at'}];const sessionCols=[{label:'用户',key:'username'},{label:'IP',key:'ip_address'},{label:'设备',key:'user_agent',format:device},{label:'状态',key:'session_status',format:(v,r)=>r.revoked_at?'已撤销':r.expires_at&&new Date(r.expires_at)<new Date()?'已过期':'活跃'},{label:'最后活动',key:'last_active_at'},{label:'登录时间',key:'created_at'}];const auditCols=[{label:'时间',key:'created_at'},{label:'用户',key:'username'},{label:'操作',key:'action',format:v=>actionNames[v]||v},{label:'对象',key:'resource_type',format:(v,r)=>r.resource_id?`${v||'资源'} #${r.resource_id}`:v||'—'},{label:'结果',key:'success',format:v=>v?'成功':'失败'},{label:'IP',key:'request_ip'}];const permissionGroups=computed(()=>Object.groupBy?Object.groupBy(permissions.value,p=>p.permission_group):permissions.value.reduce((a,p)=>((a[p.permission_group]??=[]).push(p),a),{}));
</script>
<template><div class="model-tabs account-tabs"><button v-if="can('user:view')" :class="{active:tab==='users'}" @click="switchTab('users')">用户</button><button v-if="can('role:view')" :class="{active:tab==='roles'}" @click="switchTab('roles')">角色权限</button><button v-if="can('session:manage')" :class="{active:tab==='devices'}" @click="switchTab('devices')">登录设备</button><button v-if="can('audit:view')" :class="{active:tab==='audit'}" @click="switchTab('audit')">审计日志</button></div><p v-if="message" class="notice">{{message}}</p>
<template v-if="tab==='users'"><div class="section-heading"><h2>用户账号</h2><button v-if="can('user:create')" class="primary-button" @click="newUser">新增用户</button></div><div class="table-wrap"><table><thead><tr><th v-for="c in userCols">{{c.label}}</th><th>操作</th></tr></thead><tbody><tr v-for="row in users"><td v-for="c in userCols">{{c.format?c.format(row[c.key]):row[c.key]??'—'}}</td><td><div class="row-actions"><button v-if="can('user:update')" @click="editUser(row)">编辑</button><button v-if="can('user:disable')" @click="setStatus(row)">{{row.status==='active'?'禁用':'启用'}}</button><button v-if="can('user:reset_password')" @click="createReset(row)">重置密码</button></div></td></tr></tbody></table></div><div v-if="userForm.username!==undefined" class="card editor-card"><div class="detail-heading"><h2>{{userForm.id?'编辑用户':'新增用户'}}</h2><button @click="userForm={}">关闭</button></div><div class="editor-grid"><label>用户名<input v-model="userForm.username" :disabled="!!userForm.id"></label><label>显示名称<input v-model="userForm.display_name"></label><label>邮箱<input v-model="userForm.email"></label><label>手机<input v-model="userForm.mobile"></label><label v-if="!userForm.id">初始密码<input v-model="userForm.password" type="password"></label></div><div class="check-grid"><label v-for="role in roles"><input v-model="userForm.role_ids" type="checkbox" :value="role.id">{{role.role_name}}</label></div><button class="primary-button" @click="saveUser">保存用户</button></div><div v-if="resetLink" class="card reset-result"><b>一次性重置链接</b><input :value="resetLink" readonly @focus="$event.target.select()"><button @click="navigator.clipboard.writeText(resetLink)">复制</button></div></template>
<template v-if="tab==='roles'"><div class="section-heading"><h2>角色与权限</h2><button v-if="can('role:manage')" class="primary-button" @click="newRole">新增自定义角色</button></div><div class="role-grid"><article v-for="role in roles" class="card"><h3>{{role.role_name}} <small>{{role.role_code}}</small></h3><p>{{role.description}}</p><span>{{role.permission_ids.length}} 项权限</span><div class="row-actions"><button @click="editRole(role)">{{role.is_system?'查看':'编辑'}}</button><button v-if="can('role:manage')&&!role.is_system" @click="removeRole(role)">删除</button></div></article></div><div v-if="roleForm.role_code!==undefined" class="card editor-card"><div class="detail-heading"><h2>{{roleForm.id?'角色详情':'新增角色'}}</h2><button @click="roleForm={}">关闭</button></div><div class="editor-grid"><label>角色代码<input v-model="roleForm.role_code" :disabled="!!roleForm.id"></label><label>角色名称<input v-model="roleForm.role_name" :disabled="roleForm.is_system"></label><label>说明<input v-model="roleForm.description" :disabled="roleForm.is_system"></label></div><section v-for="(items,group) in permissionGroups" class="permission-group"><b>{{group}}</b><div class="check-grid"><label v-for="permission in items"><input v-model="roleForm.permission_ids" type="checkbox" :value="permission.id" :disabled="roleForm.is_system">{{permission.permission_name}}</label></div></section><button v-if="can('role:manage')&&!roleForm.is_system" class="primary-button" @click="saveRole">保存角色</button></div></template>
<template v-if="tab==='devices'"><div class="section-heading"><h2>所有登录设备</h2><button @click="loadSessions">刷新</button></div><div class="table-wrap"><table><thead><tr><th v-for="c in sessionCols">{{c.label}}</th><th>操作</th></tr></thead><tbody><tr v-for="row in sessions"><td v-for="c in sessionCols">{{c.format?c.format(row[c.key],row):row[c.key]??'—'}}</td><td><button v-if="!row.revoked_at" @click="revoke(row)">强制退出</button></td></tr></tbody></table></div></template>
<template v-if="tab==='audit'"><div class="toolbar audit-filter"><input v-model="auditAction" placeholder="操作类型"><input v-model="auditUser" placeholder="用户名"><button @click="loadAudits(1)">查询</button></div><DataTable :columns="auditCols" :rows="audits.items" :sortable="false"/><div class="pager"><button :disabled="auditPage<=1" @click="loadAudits(auditPage-1)">上一页</button><span>共 {{audits.total||0}} 条 · 第 {{auditPage}} / {{audits.pages||1}} 页</span><button :disabled="auditPage>=audits.pages" @click="loadAudits(auditPage+1)">下一页</button></div></template>
</template>
